impl Default for IdentityBook {
    fn default() -> Self { Self::new() }
}

impl IdentityBook {
    pub fn new() -> Self { Self { next_id: 1, entries: BTreeMap::new() } }
    pub fn add(&mut self, address: String, secret: String, permission: Permission) -> Result<u64, IdentityError> {
        if address.is_empty() { return Err(IdentityError::EmptyAddress); }
        if secret.is_empty() { return Err(IdentityError::EmptySecret); }
        if self.entries.contains_key(&address) { return Err(IdentityError::DuplicateAddress); }
        let id = self.next_id;
        self.entries.insert(address.clone(), Identity { id, address, secret, permission });
        self.next_id += 1;
        Ok(id)
    }
    pub fn authenticate(&self, address: &str, secret: &str) -> bool {
        self.entries.get(address).map_or(false, |entry| entry.address == address && entry.secret == secret)
    }
    pub fn permission(&self, address: &str) -> Option<Permission> {
        self.entries.get(address).map(|entry| entry.permission)
    }
    pub fn len(&self) -> usize { self.entries.len() }
